#!/usr/bin/env bash
# bugreport.sh — collect the facts a maintainer needs to re-run and fix a report.
#
# Generated by the issue-templates kit; edit freely per project.
#
#   ./scripts/bugreport.sh                       print the block to paste into the issue
#   ./scripts/bugreport.sh --save report.txt     also write it to a file (attach that)
#   ./scripts/bugreport.sh --command "transmute convert x.mp4"   record the exact call
#   ./scripts/bugreport.sh --logs ~/.config/transmute/log.txt    append the tail of a log
#   ./scripts/bugreport.sh --path /mnt/nas/photo                 filesystem facts for a path
#   ./scripts/bugreport.sh --full                show user/host names instead of masking them
#
# Privacy: user and host names are masked by default so the block can be pasted into a public
# issue as it is.  Media file *contents* are never read — only versions, paths, sizes, settings.
# Everything is printed on screen before it goes anywhere; read it if you want.

set -u

KIT_VERSION="1.0"
MASK=1
SAVE=""
COMMAND=""
PROJECT="${BUGREPORT_PROJECT:-}"
PATHS=""
LOGS=""

have() { command -v "$1" >/dev/null 2>&1; }

while [ $# -gt 0 ]; do
  case "$1" in
    --save) SAVE="${2:-}"; shift 2 ;;
    --command) COMMAND="${2:-}"; shift 2 ;;
    --path) PATHS="$PATHS ${2:-}"; shift 2 ;;
    --logs) LOGS="$LOGS ${2:-}"; shift 2 ;;
    --project) PROJECT="${2:-}"; shift 2 ;;
    --full) MASK=0; shift ;;
    --mask) MASK=1; shift ;;
    -h|--help) sed -n '2,20p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) echo "bugreport.sh: ignoring unknown argument: $1" >&2; shift ;;
  esac
done

# Locate the project root: this script normally lives in <repo>/scripts/.
SCRIPT_DIR=$(cd "$(dirname "$0")" 2>/dev/null && pwd || echo .)
ROOT=$(cd "$SCRIPT_DIR/.." && pwd || echo "$PWD")
if [ ! -f "$ROOT/pyproject.toml" ] && [ ! -d "$ROOT/.git" ]; then ROOT="$PWD"; fi

if [ -z "$PROJECT" ]; then
  if [ -f "$ROOT/pyproject.toml" ] && grep -qm1 'name = "transmute"' "$ROOT/pyproject.toml"; then
    PROJECT=transmute
  elif [ -f "$ROOT/scripts/camera_probe.py" ] || [ -f "$ROOT/app/facecam_relay.py" ]; then
    PROJECT=facecam
  elif [ -f "$ROOT/linux/dupe_finder.py" ] || [ -f "$ROOT/windows/dupe_finder.py" ] \
       || [ -d "$ROOT/dupe_finder" ] || have dupe-finder \
       || { [ -f "$ROOT/pyproject.toml" ] && grep -qm1 'name = "duplicate-finder"' "$ROOT/pyproject.toml"; }; then
    PROJECT=dupefinder
  else
    PROJECT=generic
  fi
fi

TMP=$(mktemp "${TMPDIR:-/tmp}/bugreport.XXXXXX")
trap 'rm -f "$TMP" "${MASKSCRIPT:-}"' EXIT

# A probe that hangs must never hang the report.
if have timeout; then TOUT=timeout; else TOUT=""; fi

# esc <text> — make text safe to embed as a sed pattern (names and paths are treated as literals).
esc() { printf '%s' "$1" | sed -e 's/[][\\.^$*+?(){}|&#]/\\&/g'; }

# Build the masking rules once.  Each rule is only written when it has something to match, because
# an empty sed pattern silently reuses the previous rule and masks the wrong thing.
MASKSCRIPT=$(mktemp "${TMPDIR:-/tmp}/bugreport-mask.XXXXXX")
{
  [ -n "${HOME:-}" ]        && printf 's#%s#~#g\n' "$(esc "$HOME")"
  [ -n "${USER:-}" ]        && printf 's#%s#<user>#g\n' "$(esc "$USER")"
  uname=$(id -un 2>/dev/null || true)
  [ -n "$uname" ]           && printf 's#%s#<user>#g\n' "$(esc "$uname")"
  hn=$(hostname 2>/dev/null || true)
  [ -n "$hn" ]              && printf 's#%s#<host>#g\n' "$(esc "$hn")"
  # Windows paths reach the report when this runs in Git Bash: C:\Users\name and \\server\share.
  printf 's#[A-Za-z]:[\\/][Uu]sers[\\/][^"[:space:]:]*#<user-home>#g\n'
  printf 's#[Uu]sers[\\/][^"[:space:]/\\\\]*#<user-home>#g\n'
  # Disk and volume UUIDs are unique to one machine; a maintainer only needs to know they match.
  printf 's#[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}#<uuid>#g\n'
} > "$MASKSCRIPT"

mask() {
  # Names, home folder, host and disk UUIDs are masked so the block is safe to paste into a
  # public issue.  Use --full to keep them (private threads, or when you are the maintainer).
  if [ "$MASK" = "1" ]; then sed -E -f "$MASKSCRIPT"; else cat; fi
}

# run <label> <command...> — missing tools produce a clear note instead of a gap.
# Carriage returns are stripped because this script also runs in Git Bash on Windows, where every
# Windows tool outputs CRLF and the block would paste with stray ^M characters.
run() {
  label="$1"; shift
  label=$(printf '%s' "$label" | mask)   # labels carry user-supplied paths, so they are masked too
  if [ -z "$TOUT" ]; then out=$("$@" 2>&1 | mask | tr -d '\r' || true)
  else out=$($TOUT 5 "$@" 2>&1 | mask | tr -d '\r' || true); fi
  [ -n "$out" ] || out="(no output)"
  printf '\n### %s\n```\n%s\n```\n' "$label" "$out" >> "$TMP"
}

BEGIN="----- 8< ----- BEGIN bugreport (kit $KIT_VERSION, $PROJECT)"
END="----- 8< ----- END bugreport"

{
  echo "$BEGIN"
  echo
  echo "project: $PROJECT"
  echo "when: $(date 2>/dev/null)"
  echo "names masked: $([ "$MASK" = 1 ] && echo yes || echo no)"
  echo
  echo "### what was run"
  echo '```'
  echo "${COMMAND:-not supplied — pass --command \"the exact command you typed\"}"
  echo "cwd: $(printf '%s' "$PWD" | mask)"
  echo '```'
} > "$TMP"

# --- the machine ----------------------------------------------------------------------------
if [ -r /etc/os-release ]; then
  run "operating system" grep -E '^(PRETTY_NAME|VERSION_ID)=' /etc/os-release
elif have cmd.exe; then
  # Git Bash on Windows has no /etc/os-release; the Windows build matters more than anything else here.
  run "operating system" cmd.exe /c ver
fi
run "kernel, cpu, cores" sh -c "uname -a; echo; LC_ALL=C grep -m1 'model name' /proc/cpuinfo; echo cores: \$(nproc)"
run "memory" sh -c "free -h | head -2"
run "session and locale" sh -c "printf 'XDG_SESSION_TYPE=%s\nXDG_CURRENT_DESKTOP=%s\nLANG=%s\n' \"\${XDG_SESSION_TYPE:-unset}\" \"\${XDG_CURRENT_DESKTOP:-unset}\" \"\${LANG:-unset}\"; timedatectl 2>/dev/null | head -2 || date +%Z"

# --- the program -----------------------------------------------------------------------------
if [ -d "$ROOT/.git" ]; then
  run "program version (git)" git -C "$ROOT" log -1 --format="%h %ad %s" --date=short
  run "uncommitted changes in the checkout (if any)" git -C "$ROOT" status --porcelain
fi
if [ -f "$ROOT/pyproject.toml" ]; then
  run "declared version (pyproject)" grep -m1 -E '^version' "$ROOT/pyproject.toml"
fi
if have python3; then run "python" python3 -V; fi
if have node; then run "node" node -v; fi

case "$PROJECT" in
  transmute)
    # Transmute drives external binaries and greys out what its probe cannot prove, so a report
    # without their versions cannot be reproduced. These few lines answer most issues outright.
    # Each helper wants a different version flag — a wrong flag prints an error and buries the answer.
    for tool in ffmpeg ffprobe gs qpdf pandoc pdftoppm pdfinfo soffice; do
      have "$tool" || continue
      case "$tool" in
        pdftoppm|pdfinfo) flag="-v" ;;
        gs|soffice) flag="--version" ;;
        *) flag="-version" ;;
      esac
      run "$tool" sh -c "$tool $flag 2>&1 | head -2"
    done
    if have ffmpeg; then
      run "encoders ffmpeg can actually use" sh -c "ffmpeg -hide_banner -encoders 2>/dev/null | grep -E 'libx264|libx265|svtav1|libvpx-vp9|libaom' | head -8"
      run "hardware encode available (may be empty)" sh -c "ffmpeg -hide_banner -encoders 2>/dev/null | grep -Ei 'vaapi|nvenc|v4l2' | head -8"
    fi
    have nvidia-smi && run "nvidia" sh -c "nvidia-smi --query-gpu=name,driver_version --format=csv,noheader 2>&1 | head -2"
    run "graphics devices" sh -c "LC_ALL=C lspci 2>/dev/null | grep -iE 'vga|3d|display' | head -3"
    ;;
  facecam)
    # Camera reports are unreadable without the kernel/V4L2 state — docs/PLAN.md A.6 was built
    # from exactly these dumps, which is why they are collected automatically here.
    if have v4l2-ctl; then
      run "v4l2-ctl version" v4l2-ctl --version
      run "video devices" v4l2-ctl --list-devices
      run "camera formats and frame sizes" v4l2-ctl -d /dev/video0 --list-formats-ext
    else
      run "v4l2-ctl" sh -c "echo 'not installed — install v4l-utils and re-run'"
    fi
    run "v4l2loopback module" sh -c "if [ -d /sys/module/v4l2loopback ]; then echo loaded; for f in /sys/module/v4l2loopback/parameters/*; do printf '%s=%s\n' \"\$(basename \"\$f\")\" \"\$(cat \"\$f\" 2>/dev/null)\"; done | head -12; else echo not-loaded; fi"
    run "video node permissions" sh -c "ls -l /dev/video* 2>&1 | head -20"
    run "the Facecam on the USB bus" sh -c "lsusb 2>/dev/null | grep -i '0fd9' || echo 'Elgato (0fd9:0078) not visible'"
    ;;
  dupefinder)
    # Duplicate Finder removes or moves files it is confident are duplicates, so a report has to say
    # what the scanned location really is (its filesystem, its case behaviour) and which build ran.
    if [ -f "$ROOT/version.txt" ]; then
      run "app version (version.txt)" sh -c "cat \"\$1\"" sh "$ROOT/version.txt"
    fi
    run "python3 visible to this shell (a packaged build does not use it)" sh -c "python3 -c 'import sys,os; print(\"bundled\" if getattr(sys,\"frozen\",False) else \"from source\", os.path.basename(sys.executable))' 2>&1 | head -2"
    run "PySide6 visible to this shell" sh -c "python3 -c 'import PySide6; print(\"PySide6\", PySide6.__version__)' 2>&1 | head -2"
    run "file-name encoding seen by this shell (a packaged build may differ)" sh -c "python3 -c 'import sys; e=sys.getfilesystemencoding(); print(\"encoding\", e)' 2>&1 | head -2"
    run "recycle bin / trash available for recovery" sh -c 'ls -d "$HOME/.local/share/Trash" 2>/dev/null; command -v trash-put gio powershell.exe 2>/dev/null; echo "(a missing tool means deleted files have nowhere to go)"'
    ;;
esac

# --- the storage it touched -------------------------------------------------------------------
for p in $PATHS .; do
  [ -n "$p" ] || continue
  if [ -e "$p" ]; then
    run "filesystem behind $p" sh -c "df -hT -- '$p' | tail -2; echo; stat -f -c 'fstype=%T  blocksize=%s  free=%a blocks' -- '$p'"
    run "permissions on $p" sh -c "ls -ld -- '$p' 2>&1"
    # A duplicate finder that treats Foo.txt and foo.txt as the same file destroys data on
    # case-insensitive media (NTFS, exFAT USB sticks, SMB shares).  This measures it instead of
    # assuming it from the operating system.  It writes one temporary file that it deletes again.
    if [ "$PROJECT" = dupefinder ] && [ -w "$p" ]; then
      probe=$(mktemp "$p/.bugreport-case-XXXXXX" 2>/dev/null || true)
      if [ -n "$probe" ]; then
        dir=$(dirname "$probe"); base=$(basename "$probe")
        if [ "$base" != "$(printf '%s' "$base" | tr '[:lower:]' '[:upper:]')" ] \
           && [ -e "$dir/$(printf '%s' "$base" | tr '[:lower:]' '[:upper:]')" ]; then
          verdict="case-INSENSITIVE here: names differing only in letter case are the same file"
        else
          verdict="case-SENSITIVE here: Foo.txt and foo.txt would be different files"
        fi
        rm -f "$probe"
        printf '\n### case behaviour of that location\n%s\n' "$verdict" >> "$TMP"
      fi
    fi
  else
    printf '\n### path %s — does not exist on this machine\n' "$(printf '%s' "$p" | mask)" >> "$TMP"
  fi
done

# --- logs -------------------------------------------------------------------------------------
for f in $LOGS; do
  [ -n "$f" ] || continue
  if [ -r "$f" ]; then
    printf '\n### last 120 lines of %s (%s lines total)\n```\n' "$(printf '%s' "$f" | mask)" "$(wc -l < "$f")" >> "$TMP"
    tail -n 120 -- "$f" | mask >> "$TMP"
    printf '```\n' >> "$TMP"
  else
    printf '\n### log %s — present but not readable by this user\n' "$(printf '%s' "$f" | mask)" >> "$TMP"
  fi
done

printf '\n%s\n' "$END" >> "$TMP"

cat "$TMP"
if [ -n "$SAVE" ]; then
  if cp "$TMP" "$SAVE"; then echo "" >&2; echo "bugreport.sh: written to $SAVE" >&2; fi
fi
